import type { ActionContext } from './action_context'
import type { AgentConversation, AgentConversationEventEntry, AgentConversationMessageEntry } from './data_types'
import type { PermissionMode, ThinkingLevel } from './agent_profiles'
import type { ActionAutoFinish, ActionType } from './action_types'

export type ActionRunTerminalStatus = 'cancelled' | 'completed' | 'failed' | 'okButNotAfter'
export type ActionRunStatus = ActionRunTerminalStatus | 'queued' | 'running' | 'waitingForInput'
export type ActionRunPhase = 'after' | 'before' | 'main' | 'on'

export interface ActionRunInput {
    agent?: string
    continueFrom?: string
    extraPrompt?: string
    model?: string
    permissionMode?: PermissionMode
    prompt?: string
    thinkingLevel?: ThinkingLevel
}

export interface ActionPromptRequest {
    actionId: string
    context: ActionContext
}

export interface PreparedActionPrompt {
    prompt: string
}

export interface AgentConversationReservation {
    conversationId: string
    reference: string
}

export interface ActionStartRequest {
    actionId: string
    conversationReservation?: AgentConversationReservation
    context: ActionContext
    runInput: ActionRunInput
}

export interface AgentQuestionOption {
    description?: string
    label: string
}

export interface AgentQuestion {
    header: string
    id: string
    isOther?: boolean
    isSecret?: boolean
    options?: AgentQuestionOption[] | null
    question: string
}

export type AgentApprovalRequestId = number | string
export type AgentNetworkProtocol = 'http' | 'https' | 'socks5Tcp' | 'socks5Udp'
export type AgentFileSystemPath =
    | { path: string, type: 'path' }
    | { pattern: string, type: 'glob_pattern' }
    | { type: 'special', value: string }
export interface AgentAdditionalPermissions {
    fileSystem: {
        entries?: { access: 'deny' | 'read' | 'write', path: AgentFileSystemPath }[]
        read: string[] | null
        write: string[] | null
    } | null
    network: { enabled: boolean | null } | null
}
export type AgentCommandAction =
    | { command: string, name: string, path: string, type: 'read' }
    | { command: string, path: string | null, type: 'listFiles' }
    | { command: string, path: string | null, query: string | null, type: 'search' }
    | { command: string, type: 'unknown' }
export interface AgentNetworkPolicyAmendment {
    action: 'allow' | 'deny'
    host: string
}
export type AgentApprovalDecision =
    | 'accept'
    | 'acceptForSession'
    changeKind: ProjectWatchChangeKind
    path: string
}

/** A background agent/action currently running against a card or file. */
export interface RunningAgent {
    id: string
    label: string
}

export type AgentConversationStatus = 'cancelled' | 'completed' | 'failed' | 'running' | 'waitingForInput'
export type AgentMessageRole = 'assistant' | 'user'

export interface AgentConversationMessage {
    agent?: string
    content: string
    id: string
    role: AgentMessageRole
    sequence?: number
    timestamp: string
}

export interface AgentProviderSession {
    agent: string
    conversationId: string
    createdAt: string
    lastUsedAt: string
    synchronizedThroughMessageId: string
}

export interface AgentConversationEvent {
    command?: string
    content: string
    deletions?: number
    details?: string[]
    durationMs?: number
    exitCode?: number
    id: string
    insertions?: number
    label?: string
    output?: string
    providerItemId?: string
    sequence?: number
    status?: string
    summary?: string[]
    timestamp: string
    type: string
    workingDirectory?: string
}

export interface AgentConversationMessageEntry extends AgentConversationMessage {
    kind: 'message'
}

export interface AgentConversationEventEntry extends AgentConversationEvent {
    kind: 'event'
}

export type AgentConversationEntry = AgentConversationMessageEntry | AgentConversationEventEntry

export interface AgentTokenUsage {
    cachedInputTokens: number
    costUsd?: number
    inputTokens: number
    outputTokens: number
    reasoningTokens: number
    totalTokens: number
}

export interface AgentConversation {
    actionId?: string | null
    cardInternalId?: string | null
    cardPath: string | null
    completedAt: string | null
    entries: AgentConversationEntry[]
    hasExplicitTitle: boolean
    id: string
    path: string
    providerSessions: AgentProviderSession[]
    startedAt: string
    status: AgentConversationStatus
    title: string
    usage?: AgentTokenUsage
    viewed: boolean
}

export interface AgentConversationError {
    message: string
    path: string
}
import type { AgentConversationEvent } from '../../../data/data_types'

const COMMAND_PREVIEW_LENGTH = 96

export function eventStatusLabel(status?: string) {
    if (!status) return 'Unknown'
    if (status === 'inProgress' || status === 'running' || status === 'started') return 'Running'
    if (status === 'completed') return 'Completed'
    if (status === 'failed') return 'Failed'
    if (status === 'declined') return 'Declined'

    return status
}

export function eventHasError(status?: string) {
    return status === 'failed' || status === 'declined'
}

export function commandPreview(command?: string) {
    const oneLine = command?.replace(/\s+/gu, ' ').trim() ?? ''
    const characters = Array.from(oneLine)
    if (characters.length <= COMMAND_PREVIEW_LENGTH) return oneLine

    return `${characters.slice(0, COMMAND_PREVIEW_LENGTH - 1).join('')}â€¦`
}

export function readableEventText(value?: string) {
    return value?.trim() ? value.split(/\r?\n/u) : []
}

export function eventIdentity(event: AgentConversationEvent) {
    return event.providerItemId ?? event.id
}

